import { Canvas } from '@react-three/fiber';
import { useTexture } from '@react-three/drei';

function TexturedBox() {
  // Load textures using useTexture hook from drei
  // It automatically handles loading and returns texture objects
  const [diffuse, normal, roughness] = useTexture([
    '/textures/diffuse.jpg',
    '/textures/normal.jpg',
    '/textures/roughness.jpg'
  ]);

  return (
    <mesh>
      <boxGeometry args={[1, 1, 1]} />
      <meshStandardMaterial 
        map={diffuse}           // Diffuse/albedo texture
        normalMap={normal}      // Normal map for surface detail
        roughnessMap={roughness} // Roughness map for material variation
      />
    </mesh>
  );
}

