import { useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import * as THREE from 'three';

function VerticesExample() {
  // Create geometry from a cylinder
  // We extract the vertex positions and create a BufferGeometry
  const pointsGeometry = useMemo(() => {
    const geometry = new THREE.CylinderGeometry(0.6, 0.6, 2, 32);
    const positions = geometry.attributes.position.array;
    const bufferGeometry = new THREE.BufferGeometry();
    bufferGeometry.setAttribute(
      'position',
      new THREE.Float32BufferAttribute(positions, 3)
    );
    return bufferGeometry;
  }, []);

  return (
    <Canvas>
      <points geometry={pointsGeometry}>
        <pointsMaterial size={0.05} color="#10b981" sizeAttenuation />
      </points>
    </Canvas>
  );
}

export default VerticesExample;

import { useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { Edges } from '@react-three/drei';
import * as THREE from 'three';

function EdgesExample() {
  // Create a cylinder geometry (beer can shape)
  const canGeometry = useMemo(() => {
    return new THREE.CylinderGeometry(0.6, 0.6, 2, 32);
  }, []);

  return (
    <Canvas>
      <mesh geometry={canGeometry}>
        {/* Invisible material - we only want to see the edges */}
        <meshBasicMaterial transparent opacity={0} />
        {/* Edges component from drei draws the wireframe */}
        <Edges color="#3b82f6" threshold={0} />
      </mesh>
    </Canvas>
  );
}

export default EdgesExample;

import { useMemo } from 'react';
import { Canvas } from '@react-three/fiber';
import { Edges } from '@react-three/drei';
import * as THREE from 'three';

function FacesExample() {
  // Create the main cylinder geometry
  const canGeometry = useMemo(() => {
    return new THREE.CylinderGeometry(0.6, 0.6, 2, 32);
  }, []);

  // Create edges geometry for wireframe overlay
  const edgesGeometry = useMemo(() => {
    const geometry = new THREE.CylinderGeometry(0.6, 0.6, 2, 32);
    return new THREE.EdgesGeometry(geometry);
  }, []);

  // Get accent color from CSS variable (fallback to teal)
  const accentColor = typeof window !== 'undefined'
    ? getComputedStyle(document.documentElement).getPropertyValue('--color-accent').trim() || '#14b8a6'
    : '#14b8a6';

  return (
    <Canvas>
      <mesh geometry={canGeometry}>
        {/* Standard material with PBR properties using accent color */}
        <meshStandardMaterial 
          color={accentColor} 
          metalness={0.8}
          roughness={0.2}
        />
        {/* Optional: Add edges overlay to see the structure */}
        <Edges geometry={edgesGeometry} color="#000000" threshold={0} />
      </mesh>
    </Canvas>
  );
}

export default FacesExample;

import { useLayoutEffect } from 'react';
import { Canvas } from '@react-three/fiber';
import { useGLTF } from '@react-three/drei';
import { useTexture } from '@react-three/drei';
import * as THREE from 'three';

function BeerCan({ texturePath }: { texturePath: string }) {
  const { scene } = useGLTF('/Beer.gltf');
  const texture = useTexture(texturePath);

  // Apply texture to the model's materials
  useLayoutEffect(() => {
    scene.traverse((obj: any) => {
      if (obj.isMesh && obj.material) {
        // Apply the texture to the material
        obj.material.map = texture;
        obj.material.needsUpdate = true;
      }
    });
  }, [scene, texture]);

  return <primitive object={scene} />;
}

function Scene({ texturePath }: { texturePath: string }) {
  return (
    <Canvas>
      <BeerCan texturePath={texturePath} />
      <ambientLight intensity={0.5} />
      <directionalLight position={[5, 5, 5]} intensity={1} />
    </Canvas>
  );
}

export default Scene;
